}

/**
 * Agrega una nueva hoja (página) al reporte con encabezado y pie de página opcionales.
 *
 * @param bool $mostrar_encabezado Si es true, renderiza el encabezado de antecedentes. Por defecto true.
 * @param bool $mostrar_pie_pagina Si es true, renderiza el pie de página de antecedentes. Por defecto true.
 * @return void
 * @author Jair Carvajal
 */
public function agregarHoja($mostrar_encabezado = true, $mostrar_pie_pagina = true): void {
    $this->mpdf->AddPage();

    if ($mostrar_encabezado) {
        $this->mostrarEncabezadoAntecedente();
    }

    if ($mostrar_pie_pagina) {
        $this->mostrarPiePaginaAntecedente();
    }
}

/**
 * Renderiza el encabezado del reporte de antecedentes.
 * Muestra el logo de PsicoAlianza, el logo de la empresa (si existe),
 * el avatar generado del candidato, y sus datos principales
 * (nombre, identificación, género, RUT, estado).
 *
 * @return void
 * @author Jair Carvajal
 */
public function mostrarEncabezadoAntecedente(): void {
    $datos           = $this->datos_antecedente ?? [];
    $colores_reporte = $this->colores_reporte;

    $nombre       = $datos['nombre'] ?? 'Sin nombre';
    $documento    = $datos['documento'] ?? '';
    $estado       = $datos['rut_estado'] ?? '';
    $nivel_riesgo = $datos['nivel_riesgo'] ?? '';
    $genero       = $datos['genero'] ?? '';
    $rut          = $datos['rut'] ?? '';
    $empresa_id   = $datos['empresa_id'] ?? 1;

    $this->mostrarImagen((object) [
        'url' => public_path('imagenes/reportes/antecedentes/logo_antecedentes.png'),
        'x'   => 5, 'y' => 0, 'width' => 24,
    ]);

    try {
        $logo = $this->archivo_repositorio->getUnoAvanzado(new Request([
            'modelo'    => 'App\Models\Empresas\Empresa',
            'modelo_id' => $empresa_id,
            'nombre'    => 'logo',
        ]));

        if ($logo && $logo->ruta) {
            $ruta_limpia = $logo->ruta;

            if (str_starts_with($ruta_limpia, 'private/archivos/')) {
                $ruta_limpia = substr($ruta_limpia, strlen('private/archivos/'));
            }

            if (Storage::disk('archivos')->exists($ruta_limpia)) {
                $contenido_logo = Storage::disk('archivos')->get($ruta_limpia);

                if (!empty($contenido_logo)) {
                    $extension    = strtolower(pathinfo($ruta_limpia, PATHINFO_EXTENSION));
                    $formato_mime = match ($extension) {
                        'png' => 'png',
                        'jpg', 'jpeg' => 'jpeg',
                        'gif'   => 'gif',
                        'webp'  => 'webp',
                        default => 'jpeg',
                    };

                    $this->mpdf->WriteHTML('
                        <div style="position: absolute; left: 36mm; top: 7mm;">
                            <img src="data:image/' . $formato_mime . ';base64,' . base64_encode($contenido_logo) . '"
                                 style="height: 12mm; max-width: 40mm; min-width: 23mm; object-fit: contain;">
                        </div>
                    ');
                }
            }
        }
    } catch (Throwable $error) {
        // Continuar sin logo de empresa
    }

    $this->mostrarImagen((object) [
        'url' => public_path('imagenes/reportes/antecedentes/icono-proceso.png'),
        'x'   => 152, 'y' => 18, 'height' => 13,
    ]);

    $this->mostrarImagen((object) [
        'url' => public_path('imagenes/reportes/encabezado/marco-candidato.png'),
        'x'   => 91, 'y' => 16, 'width' => 17, 'height' => 14.2,
    ]);

    $partes = explode(' ', trim($nombre), 2);
    $svg    = $this->generarAvatarSVG($partes[0] ?? '', $partes[1] ?? '', (string) ($datos['id'] ?? '1'), $colores_reporte[0]);
    $this->mostrarImagen((object) [
        'contenido' => $svg,
        'formato'   => 'svg+xml',
        'x'         => 93, 'y' => 16.5, 'width' => 12.8, 'height' => 12.8,
    ]);

    $this->mostrarNombreProceso((object) [
        'x'               => 88, 'y' => 4, 'width' => 116, 'height' => 5,
        'nombre_proceso'  => 'Consulta de Antecedentes',
        'colores_reporte' => $colores_reporte,
    ]);

    $this->mostrarDatosProceso((object) [
        'x'               => 108.5, 'y' => 16.5,
        'titulo'          => 'Nombre', 'valor' => $nombre,
        'colores_reporte' => $colores_reporte,
    ]);
    $this->mostrarDatosProceso((object) [
        'x'               => 108.5, 'y' => 21.5,
        'titulo'          => 'Identificación', 'valor' => $documento,
        'colores_reporte' => $colores_reporte,
    ]);
    $this->mostrarDatosProceso((object) [
        'x'               => 108.5, 'y' => 26.5,
        'titulo'          => 'Género', 'valor' => ucfirst($genero),
