/**
 * Renderiza la página de resumen ejecutivo del reporte.
 * Muestra una alerta con el nivel de riesgo general (alto, medio, bajo)
 * y tres tarjetas que resumen:
 * - Total de fuentes con resultados
 * - Total de fuentes sin resultados
 * - Total de fuentes no disponibles (con error), listadas en dos columnas
 *
 * @return void
 * @author Jair Carvajal
 */
public function paginaResumenEjecutivo(): void {
    $datos         = $this->datos_antecedente ?? [];
    $con_resultado = $datos['con_resultado'] ?? [];
    $sin_resultado = $datos['sin_resultado'] ?? [];
    $con_error     = $datos['con_error'] ?? [];

    $total_con_resultado = count($con_resultado);
    $total_sin_resultado = count($sin_resultado);
    $total_con_error     = count($con_error);

    $mitad     = (int) ceil($total_con_error / 2);
    $columna_1 = array_slice($con_error, 0, $mitad);
    $columna_2 = array_slice($con_error, $mitad);

    $elementos_columna_1 = implode('', array_map(
        fn($nombre_fuente) => '<div style="line-height: 5.5mm; font-size: 10px;">&#8226; ' . $nombre_fuente . '</div>',
        $columna_1
    ));
    $elementos_columna_2 = implode('', array_map(
        fn($nombre_fuente) => '<div style="line-height: 5.5mm; font-size: 10px;">&#8226; ' . $nombre_fuente . '</div>',
        $columna_2
    ));

    $nivel_riesgo = strtolower($datos['nivel_riesgo'] ?? 'alto');

    $alerta = match ($nivel_riesgo) {
        'bajo' => [
            'fondo'   => '#D4EDDA',
            'borde'   => '#C3E6CB',
            'texto'   => '#155724',
            'mensaje' => 'Hemos encontrado hallazgos bajos en tu consulta. Te recomendamos revisar el reporte de forma detallada para tomar las mejores decisiones..',
        ],
        'medio' => [
            'fondo'   => '#FFF3CD',
            'borde'   => '#FFEEBA',
            'texto'   => '#856404',
            'mensaje' => 'Hemos encontrado hallazgos medios en tu consulta. Te recomendamos revisar el reporte de forma detallada para tomar las mejores decisiones.',
        ],
        default => [
            'fondo'   => '#F8D7DA',
            'borde'   => '#F5C6CB',
            'texto'   => '#721C24',
            'mensaje' => 'Hemos encontrado hallazgos altos en tu consulta. Te recomendamos revisar el reporte de forma detallada para tomar las mejores decisiones.',
        ],
    };

    $this->tituloSeccionHoja((object) [
        'y'      => 35,
        'width'  => 62,
        'titulo' => 'RESUMEN EJECUTIVO',
        'color'  => $this->colores_reporte[0],
    ]);

    $this->mpdf->WriteHTML('
        <div style="
            position: absolute; left: 10mm; top: 48mm;
            width: 181mm; padding: 4mm 6mm;
