            border: 0.4mm solid ' . $alerta['borde'] . ';
            border-radius: 2mm; color: ' . $alerta['texto'] . ';
        ">
            <div style="font-weight: 600; font-size: 12px; line-height: 16px;">
                ' . $alerta['mensaje'] . '
            </div>
        </div>
    ');

    $icono_arriba = base64_encode($this->generarBadgeContadorSVG(
        '<path fill-rule="evenodd" d="M10.854 6.146a.5.5 0 0 1 0 .708l-3 3a.5.5 0 0 1-.708 0l-1.5-1.5a.5.5 0 1 1 .708-.708L7.5 8.793l2.646-2.647a.5.5 0 0 1 .708 0z"/><path d="M3 0h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2v-1h1v1a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v1H1V2a2 2 0 0 1 2-2z"/><path d="M1 5v-.5a.5.5 0 0 1 1 0V5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0V8h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0v.5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1z"/>',
        $total_con_resultado
    ));
    $icono_abajo = base64_encode($this->generarBadgeContadorSVG(
