public function paginaListasPrecargadas(float $altura_inicial = 48): void {
    $color              = $this->colores_reporte[0];
    $datos              = $this->datos_antecedente ?? [];
    $listas_precargadas = $datos['listas_precargadas'] ?? [];

    $categorias = [
        'listas_vinculantes'   => 'Listado de vinculantes',
        'listas_restrictivas'  => 'Listas restrictivas',
        'noticias_criminales'  => 'Noticias criminales',
        'boletines'            => 'Boletines',
        'figuras_publicas'     => 'Figuras públicas',
        'contratacion_publica' => 'Contratación pública',
        'peps'                 => 'PEP',
        'peps_internacionales' => 'PEP internacionales',
        'offshoreleaks'        => 'Offshore leaks database (ICIJ)',
    ];

    $this->tituloSeccionHoja((object) [
        'y'      => 35,
        'width'  => 75,
        'titulo' => 'LISTAS PRECARGADAS',
        'color'  => $color,
    ]);

    $this->mpdf->SetY($altura_inicial);
    $this->mpdf->WriteHTML('
        <div style="font-size: 12px; font-weight: 600; line-height: 16px; letter-spacing: 0.5px; color: #4D4D4F; margin-bottom: 5mm;">
            Esta seccion consolida bases de datos nacionales e internacionales sobre sanciones, PEP, terrorismo,
            corrupcion, inhabilidades, fugitivos y restricciones comerciales, provenientes de organismos oficiales,
            entidades regulatorias y autoridades judiciales, permitiendo una validacion integral de riesgos legales,
            financieros y reputacionales.
        </div>
        <div style="font-size: 12px; font-weight: 600; line-height: 16px; letter-spacing: 0.5px; border: 0.3mm solid #1BB8F340; border-radius: 2mm; padding: 4mm; background-color: #D1ECF1; color: #0C5460; margin-bottom: 5mm;">
            El resultado de esta consulta es producto de la busqueda de datos con base a los nombres y
            apellidos de la persona sobre quien se pide la informacion. Dada la existencia de homonimos,
            puede ser que la informacion corresponda a otra persona que tenga los mismos nombres y apellidos.
        </div>
    ');

    $sin_datos_titulos     = [];
    $sin_resultado_titulos = [];

    // Pre-conteo de categorías con hallazgos para el badge
    $total_con_hallazgos = 0;

    foreach ($categorias as $clave => $etiqueta_categoria) {
        $dato_categoria = $listas_precargadas[$clave] ?? null;

        if ($this->tieneResultados($dato_categoria)) {
            $total_con_hallazgos++;
        }
    }

    $rutas_icono_check  = '<path fill-rule="evenodd" d="M10.854 6.146a.5.5 0 0 1 0 .708l-3 3a.5.5 0 0 1-.708 0l-1.5-1.5a.5.5 0 1 1 .708-.708L7.5 8.793l2.646-2.647a.5.5 0 0 1 .708 0z"/><path d="M3 0h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2v-1h1v1a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v1H1V2a2 2 0 0 1 2-2z"/><path d="M1 5v-.5a.5.5 0 0 1 1 0V5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0V8h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0v.5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1z"/>';
    $insignia_hallazgos = base64_encode($this->generarBadgeContadorSVG($rutas_icono_check, $total_con_hallazgos));

    if ($total_con_hallazgos > 0) {
        $this->mpdf->WriteHTML('
            <div style="padding: 4mm; border: 0.3mm solid #E0E0E0; border-bottom: none; border-radius: 2mm 2mm 0 0; margin-top: 2mm; background-color: #FFFFFF; overflow: hidden;">
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>
                        <td style="font-size: 13px; font-weight: bold; color: #1C1C1D; vertical-align: middle;">
                            Fuentes con hallazgos
                        </td>
                        <td style="text-align: right; vertical-align: middle; width: 10%; white-space: nowrap;">
                            <img src="data:image/svg+xml;base64,' . $insignia_hallazgos . '" style="height: 5mm; vertical-align: middle;">
                        </td>
                    </tr>
                </table>
            </div>
        ');

        foreach ($categorias as $clave => $etiqueta) {
            $datos_categoria = $listas_precargadas[$clave] ?? null;

            if ($clave === 'offshoreleaks') {
                $this->renderizarSeccionOffshoreleaks($datos_categoria, $sin_datos_titulos, $sin_resultado_titulos);
                continue;
            }

            if ($this->esSinDatosPrecargados($datos_categoria)) {
                $sin_datos_titulos[] = $etiqueta;
            } else {
                $this->renderizarSeccionConDatos($etiqueta, (array) $datos_categoria, $sin_resultado_titulos, 'LISTAS PRECARGADAS');
            }
        }
    }

    $tiene_sin_hallazgos = !empty($sin_datos_titulos) || !empty($sin_resultado_titulos);

    if ($tiene_sin_hallazgos) {
        $total_sin_hallazgos = count($sin_datos_titulos) + count($sin_resultado_titulos);
        $rutas_icono_menos   = '<path fill-rule="evenodd" d="M10.5 8a.5.5 0 0 1-.5.5H6a.5.5 0 0 1 0-1h4a.5.5 0 0 1 .5.5z"/><path d="M3 0h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2v-1h1v1a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v1H1V2a2 2 0 0 1 2-2z"/><path d="M1 5v-.5a.5.5 0 0 1 1 0V5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0V8h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0v.5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1z"/>';
        $insignia_sin        = base64_encode($this->generarBadgeContadorSVG($rutas_icono_menos, $total_sin_hallazgos));

        $generar_columnas_html = function (array $lista, int $num_cols): string {
            $total               = count($lista);
            $items_por_columna   = (int) ceil($total / $num_cols);
            $ancho_columna       = (int) round(100 / $num_cols);
            $html_columnas_tabla = '';

            for ($i = 0; $i < $num_cols; $i++) {
                $items_columna = array_slice($lista, $i * $items_por_columna, $items_por_columna);
                $html_items    = implode('', array_map(
                    fn($nombre_fuente) => '<div style="font-size: 10px; color: #4D4D4F; line-height: 5.5mm;">&#8226; ' . htmlspecialchars($nombre_fuente) . '</div>',
                    $items_columna
                ));
                $html_columnas_tabla .= '<td style="width: ' . $ancho_columna . '%; vertical-align: top;">' . $html_items . '</td>';
            }
            return '<table style="width: 100%; border-collapse: collapse;"><tr>' . $html_columnas_tabla . '</tr></table>';
        };

        $html_sin_datos     = '';
        $html_sin_resultado = '';

        if (!empty($sin_datos_titulos)) {
            $html_sin_datos = '
                <div style="margin-bottom: 3mm;">
                    <div style="font-size: 10px; font-weight: bold; color: #1C1C1D; margin-bottom: 2mm;">Fuentes sin datos disponibles</div>
                    <div style="font-size: 10px; color: #4D4D4F; margin-bottom: 2mm;">Se realiz&#243; una b&#250;squeda en las siguientes fuentes y no se encontraron registros relacionados con la persona consultada.</div>
                    ' . $generar_columnas_html($sin_datos_titulos, 2) . '
                </div>
            ';
        }

        if (!empty($sin_resultado_titulos)) {
            $separador          = !empty($sin_datos_titulos) ? '<div style="border-top: 0.2mm solid #E0E0E0; margin: 3mm 0;"></div>' : '';
            $html_sin_resultado = '
                ' . $separador . '
                <div>
                    <div style="margin-bottom: 3mm;">
                        <table style="width: 100%; border-collapse: collapse;">
                            <tr>
                                <td style="font-size: 13px; font-weight: bold; color: #1C1C1D; vertical-align: middle;">
                                    Fuentes sin hallazgos
                                </td>
                                <td style="text-align: right; vertical-align: middle; width: 10%; white-space: nowrap;">
                                    <img src="data:image/svg+xml;base64,' . $insignia_sin . '" style="height: 5mm; vertical-align: middle;">
                                </td>
                            </tr>
                        </table>
                    </div>
                    <div style="font-size: 10px; color: #4D4D4F; margin-bottom: 2mm;">Se realizó; una búsqueda en diferentes bases de datos y fuentes oficiales. Como resultado, no se encontraron registros ni documentos relacionados con la persona consultada. <br><br> Las fuentes consultadas sin resultados fueron:</div>
                    ' . $generar_columnas_html($sin_resultado_titulos, 3) . '
                </div>
            ';
        }

        $this->mpdf->WriteHTML('
            <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; margin-bottom: 4mm; background-color: #FFFFFF; overflow: hidden;">
                <div style="padding: 4mm;">
                    ' . $html_sin_datos . $html_sin_resultado . '
                </div>
            </div>
        ');
    }
}

/**
 * Renderiza la página de listas en línea del reporte.
 * Muestra las categorías presentes en listas_linea como secciones con sus datos.
 * Si el array está vacío o no existe, muestra la card predeterminada de sin resultados.
 * Si una categoría no tiene datos válidos, la omite y la acumula para el bloque de sin resultados.
 *
 * @param float $altura_inicial Posición Y en milímetros desde donde empieza el contenido. Por defecto 48.
 * @return void
 * @author Jair Carvajal
 */
public function paginaListasLinea(float $altura_inicial = 48): void {
    $color        = $this->colores_reporte[0];
    $datos        = $this->datos_antecedente ?? [];
    $listas_linea = $datos['listas_linea'] ?? [];

    $this->tituloSeccionHoja((object) [
        'y'      => 35,
        'width'  => 70,
        'titulo' => 'LISTAS EN LINEA',
        'color'  => $color,
    ]);

    $this->mpdf->SetY($altura_inicial);

    if (empty($listas_linea)) {
        $this->mpdf->WriteHTML('
            <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; background-color: #FFFFFF; overflow: hidden;">
                <div style="padding: 4mm; text-align: center; color: #9E9E9E; font-size: 10px; font-style: italic;">
                    Sin datos encontrados
                </div>
            </div>
        ');
        return;
    }

    $sin_resultado_titulos = [];

    foreach ($listas_linea as $etiqueta => $datos_categoria) {
        if ($this->esSinDatosPrecargados($datos_categoria)) {
            $sin_resultado_titulos[] = (string) $etiqueta;
            continue;
        }

        $this->renderizarSeccionConDatos((string) $etiqueta, (array) $datos_categoria, $sin_resultado_titulos, 'LISTAS EN LINEA');
    }

    if (!empty($sin_resultado_titulos)) {
        $this->renderizarTarjetaLista(
            'Fuentes sin resultados encontrados',
            'Se realizó una búsqueda en las siguientes fuentes y no se encontraron registros relacionados con la persona consultada.',
            $sin_resultado_titulos,
            2
        );
    }
}

/**
 * Determina si el valor de una categoría de listas precargadas no tiene datos válidos.
 *
 * @param mixed $datos Valor a evaluar.
 * @return bool true si el dato es null, false, array vacío o string 'Error'.
 * @author Jair Carvajal
 */
private function esSinDatosPrecargados(mixed $datos): bool {
    return $datos === null || $datos === false || $datos === [] || $datos === 'Error';
}

/**
 * Renderiza el bloque HTML de una categoría sin datos encontrados.
 *
 * @param string $etiqueta Nombre legible de la categoría a mostrar como encabezado.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarSeccionSinDatos(string $etiqueta): void {
    $color = $this->colores_reporte[0];

    $this->mpdf->WriteHTML('
        <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; margin-bottom: 4mm; background-color: #FFFFFF; overflow: hidden;">
            <div style="background-color: ' . $color . '1A; padding: 2.5mm 4mm; border-bottom: 0.3mm solid #E0E0E0;">
                <span style="font-size: 11px; font-weight: bold; color: #1C1C1D;">' . htmlspecialchars($etiqueta) . '</span>
            </div>
            <div style="padding: 4mm; text-align: center; color: #9E9E9E; font-size: 10px; font-style: italic;">
                Sin datos encontrados
            </div>
        </div>
    ');
}

/**
 * Renderiza la sección Offshore leaks database (ICIJ) con sus cinco sub-categorías.
 * Las sub-categorías sin datos se acumulan en $sin_datos_titulos para la sección global.

