/**
 * Renderiza la sección Offshore leaks database (ICIJ) con sus cinco sub-categorías.
 * Las sub-categorías sin datos se acumulan en $sin_datos_titulos para la sección global.
 * Si el valor global de offshoreleaks es sin datos, se agrega su título a la lista y no se renderiza nada.
 *
 * @param mixed $datos_offshore Valor completo de la clave offshoreleaks en listas_precargadas.
 * @param array $sin_datos_titulos Lista de títulos sin resultado, se modifica por referencia.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarSeccionOffshoreleaks(mixed $datos_offshore, array &$sin_datos_titulos, array &$sin_resultado_titulos): void {
    $sub_categorias = [
        'Bahamas Leaks'   => 'Bahamas Leaks',
        'Offshore Leaks'  => 'Offshore Leaks',
        'Panama Papers'   => 'Panama Papers',
        'Pandora Papers'  => 'Pandora Papers',
        'Paradise Papers' => 'Paradise Papers',
    ];

    if ($this->esSinDatosPrecargados($datos_offshore)) {
        foreach ($sub_categorias as $etiqueta_sub) {
            $sin_datos_titulos[] = $etiqueta_sub;
        }
        return;
    }

    $datos_offshore      = (array) $datos_offshore;
    $sub_categorias_html = '';

    foreach ($sub_categorias as $clave_sub => $etiqueta_sub) {
        $datos_sub = $datos_offshore[$clave_sub] ?? null;

        if ($this->esSinDatosPrecargados($datos_sub)) {
            $sin_datos_titulos[] = $etiqueta_sub;
            continue;
        }

        $filas_sub       = (array) $datos_sub;
        $columnas_vacias = [];
        $columnas        = array_keys((array) ($filas_sub[0] ?? []));

        if (empty($this->filtrarColumnasConDatos($filas_sub, $columnas, $columnas_vacias))) {
            $sin_datos_titulos[] = $etiqueta_sub;
            continue;
        }

        if (!$this->tieneResultados($filas_sub)) {
            $sin_resultado_titulos[] = $etiqueta_sub;
            continue;
        }

        $html_encabezados = implode('', array_map(
            fn($col) => '<th style="padding: 1.5mm 3mm; text-align: left; font-size: 9px; font-weight: bold; color: #1C1C1D; background-color: #F2F2F7; border-right: 0.2mm solid #E0E0E0;">'
                . htmlspecialchars(ucwords(str_replace('_', ' ', $col)))
                . '</th>',
            $columnas
        ));

        $html_filas = '';

        foreach ($filas_sub as $indice => $fila) {
            $fila       = (array) $fila;
            $fondo_fila = $indice % 2 === 0 ? '#FFFFFF' : '#F7F7F7';
            $celdas     = implode('', array_map(function ($col) use ($fila) {
                $valor = $fila[$col] ?? '';

                if (is_array($valor) || is_object($valor)) {
                    $valor = json_encode($valor, JSON_UNESCAPED_UNICODE);
                }
                return '<td style="padding: 1.5mm 3mm; font-size: 9px; color: #4D4D4F; border-right: 0.2mm solid #EBEBEB; border-bottom: 0.2mm solid #F0F0F0;">'
                    . htmlspecialchars((string) $valor)
                    . '</td>';
            }, $columnas));
            $html_filas .= '<tr style="background-color: ' . $fondo_fila . ';">' . $celdas . '</tr>';
        }

        $sub_categorias_html .= '
            <div style="border-top: 0.2mm solid #E0E0E0; padding: 2mm 4mm 1mm 4mm; background-color: #FAFAFA;">
                <span style="font-size: 10px; font-weight: bold; color: #4D4D4F;">' . htmlspecialchars($etiqueta_sub) . '</span>
            </div>
            <table style="width: 100%; border-collapse: collapse; margin-bottom: 1mm;">
                <thead><tr>' . $html_encabezados . '</tr></thead>
                <tbody>' . $html_filas . '</tbody>
            </table>
        ';
    }

    if (empty($sub_categorias_html)) {
        return;
    }

    $this->mpdf->WriteHTML('
        <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; margin-bottom: 4mm; background-color: #FFFFFF; overflow: hidden;">
            <div style="background-color: #F2F2F7; padding: 2.5mm 4mm; border-bottom: 0.3mm solid #E0E0E0;">
                <span style="font-size: 11px; font-weight: bold; color: #1C1C1D;">Offshore leaks database (ICIJ)</span>
            </div>
            ' . $sub_categorias_html . '
        </div>
    ');
}

/**
 * Renderiza la sección global de fuentes consultadas sin resultados.
 *
 * @param array $titulos Lista de nombres de fuentes sin resultado.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarSeccionResultadosNoEncontrados(array $titulos): void {
    $this->renderizarTarjetaLista(
        'Fuentes sin resultados encontrados',
        'Se realizó una búsqueda en las siguientes fuentes y no se encontraron registros relacionados con la persona consultada.',
        $titulos,
        2
    );
}

/**
 * Filtra las columnas de un dataset y devuelve solo las que tienen al menos un valor no vacío.
 * Las columnas completamente vacías se acumulan en $columnas_vacias por referencia.
 *
 * @param array $filas Filas del dataset a evaluar.
 * @param array $columnas Lista completa de columnas a filtrar.
 * @param array $columnas_vacias Lista de columnas sin datos, se modifica por referencia.
 * @return array Columnas que contienen al menos un valor con información.
 * @author Jair Carvajal
 */
private function filtrarColumnasConDatos(array $filas, array $columnas, array &$columnas_vacias): array {
    $columnas_con_datos = [];

    foreach ($columnas as $col) {
        $tiene_dato = false;

        foreach ($filas as $fila) {
            $valor = ((array) $fila)[$col] ?? null;

            if ($valor !== null && $valor !== '' && $valor !== [] && $valor !== false) {
                $tiene_dato = true;
                break;
            }
        }

        if ($tiene_dato) {
            $columnas_con_datos[] = $col;
        } else {
            $columnas_vacias[] = $col;
        }
    }

    return $columnas_con_datos;
}

/**
 * Renderiza un registro individual como tabla de 4 columnas: parámetro | valor | parámetro | valor.
 * Excluye el campo CODIGO y renombra ROL_O_DESCRIPCION1/2 a Detalles/Observaciones.
 *
 * @param array $fila Registro a mostrar como array asociativo.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarTablaRegistro(array $fila): void {
    $excluir   = ['CODIGO', 'codigo', 'Codigo'];
