        'ROL_O_DESCRIPCION1'        => 'Detalles',
        'ROL_O_DESCRIPCION2'        => 'Observaciones',
        'AKA'                       => 'Alias',
        'CATEGORIA'                 => 'Categoría',
        'DIRECCION'                 => 'Dirección',
        'ESTADO'                    => 'Estado',
        'FECHA_FINAL_ROL'           => 'Fecha final',
        'FECHA_UPDATE'              => 'Fecha de actualización',
        'FUENTE'                    => 'Fuente',
        'ID'                        => 'Identificación',
        'LLAVEIMAGEN'               => 'Llave',
        'NACIONALIDAD_PAISDEORIGEN' => 'Nacionalidad',
        'NOMBRECOMPLETO'            => 'Nombre completo',
        'ORIGEN_LISTA'              => 'Origen de lista',
        'PRIMER_APELLIDO'           => 'Primer apellido',
        'PRIMER_NOMBRE'             => 'Primer nombre',
        'RELACIONADO_CON'           => 'Relacionado con',
        'SEGUNDO_APELLIDO'          => 'Segundo apellido',
        'SEGUNDO_NOMBRE'            => 'Segundo nombre',
        'TIPO_ID'                   => 'Tipo de documento',
        'TIPO_LISTA'                => 'Tipo de lista',
        'TIPO_PERSONA'              => 'Tipo de entidad',
    ];

    $campos = array_filter(
        $fila,
        fn($v, $k) => !is_array($v) && !is_object($v) && !in_array($k, $excluir, true),
        ARRAY_FILTER_USE_BOTH
    );

    $pares      = array_chunk(array_keys($campos), 2);
    $html_filas = '';

    foreach ($pares as $indice_par => $par) {
        $fondo   = $indice_par % 2 === 0 ? '#FFFFFF' : '#F7F7F7';
        $clave_1 = $par[0];
        $valor_1 = htmlspecialchars((string) ($campos[$clave_1] ?? ''));

