/**
 * Renderiza el bloque HTML de una categoría con datos en formato tabla.
 * Solo pinta las filas que tengan 'resultado' no vacío. Las filas sin resultado
 * se renderizan en una tarjeta aparte con sus identificadores en 3 columnas.
 * Si ninguna fila tiene resultado, acumula la etiqueta en $sin_resultado_titulos.
 * Cuando el contenido no cabe en la página actual, agrega una hoja nueva con el
 * título de sección y reabre el contenedor de la categoría.
 *
 * @param string $etiqueta Nombre legible de la categoría.
 * @param array $datos Array de registros a mostrar, cada uno como array u objeto.
 * @param array $sin_resultado_titulos Lista acumulada de títulos sin resultado, por referencia.
 * @param string $titulo_seccion Título de la sección padre para los saltos de página.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarSeccionConDatos(string $etiqueta, array $datos, array &$sin_resultado_titulos, string $titulo_seccion = 'LISTAS PRECARGADAS'): void {
    if (empty($datos)) {
        return;
    }

    $color                 = $this->colores_reporte[0];
    $columnas              = array_keys((array) $datos[0]);
    $filas_con_resultado   = [];
    $titulos_sin_resultado = [];

    foreach ($datos as $fila) {
        $fila = (array) $fila;

        if (!empty($fila['resultado'])) {
            $filas_con_resultado[] = $fila;
        } else {
            $titulo_item             = $fila['nombre'] ?? $fila['name'] ?? $fila['titulo'] ?? reset($fila);
            $titulos_sin_resultado[] = (string) $titulo_item;
        }
    }

    if (empty($filas_con_resultado)) {
        $sin_resultado_titulos[] = $etiqueta;
        return;
    }

    $limite_pagina       = 265;
    $excluir_altura      = ['CODIGO', 'codigo', 'Codigo'];
    $num_registro_global = 0;

    $abrir_en_nueva_pagina = function () use ($titulo_seccion, $color): void {
        $this->tituloSeccionHoja((object) [
            'y'      => 35,
            'width'  => 75,
            'titulo' => $titulo_seccion,
            'color'  => $color,
        ]);
        $this->mpdf->SetY(48);
    };

    foreach ($filas_con_resultado as $fila) {
        $nombre_lista = htmlspecialchars($fila['nombre_lista'] ?? $fila['NOMBRE_LISTA'] ?? '');
        $tipo_lista   = htmlspecialchars($fila['tipo_lista'] ?? $fila['TIPO_LISTA'] ?? '');
        $registros    = (array) ($fila['resultado'] ?? []);

        foreach ($registros as $registro) {
            $registro         = (array) $registro;
            $campos_filtrados = array_filter($registro, fn($v, $k) => !is_array($v) && !is_object($v) && !in_array($k, $excluir_altura, true), ARRAY_FILTER_USE_BOTH);
            $altura_estimada  = (int) ceil(count($campos_filtrados) / 2) * 6 + 14;
            $num_registro_global++;

            if ($this->mpdf->y + $altura_estimada > $limite_pagina) {
                $this->mpdf->WriteHTML('</div>');
                $this->agregarHoja();
                $abrir_en_nueva_pagina();
            }

            $borde_top = $num_registro_global > 1 ? 'margin-top: 3mm;' : 'margin-top: -2mm;';
            $this->mpdf->WriteHTML('
                <div class="padding: 0mm 4mm; margin-left: 4mm; margin-right: 4mm;">
                    <div style="' . $borde_top . ' padding: 2mm 4mm; border-top: 0.3mm solid #E0E0E0;  border-left: 0.3mm solid #E0E0E0; border-right: 0.3mm solid #E0E0E0; background-color: #FAFAFA;">
                        <span style="font-size: 9px; font-weight: bold; color: #1C1C1D;">' . $nombre_lista . '</span>
                        ' . ($tipo_lista ? '<span style="font-size: 8px; color: #888888; margin-left: 3mm;">(' . $tipo_lista . ')</span>' : '') . '
                    </div>
                </div>
            ');

            $this->renderizarTablaRegistro($registro);
        }
    }

    if (!empty($titulos_sin_resultado)) {
        $this->mpdf->WriteHTML('<div style="margin-top: 3mm;">');
        $this->renderizarTarjetaLista(
            'Fuentes sin hallazgos en ' . $etiqueta,
            'Los siguientes registros fueron encontrados pero no contienen resultado asociado.',
            $titulos_sin_resultado,
            3
        );
        $this->mpdf->WriteHTML('</div>');
    }
}

/**
 * Verifica si algún elemento del array tiene datos en la clave 'resultado'.
 *
 * @param array $listas Array de registros a evaluar.
 * @return bool true si al menos uno tiene 'resultado' no vacío.
 * @author Jair Carvajal
 */
private function tieneResultados(array $listas): bool {
    foreach ($listas as $lista) {
        if (!empty($lista['resultado'])) {
            return true;
        }
    }
    return false;
}

/**
 * Renderiza una tarjeta informativa con título, descripción y lista de ítems en N columnas.
 * Reutilizable para mostrar resúmenes de fuentes sin resultado, no disponibles, etc.
 *
 * @param string $titulo Encabezado principal de la tarjeta.
 * @param string $texto Descripción explicativa mostrada debajo del título.
 * @param array $lista_textos Ítems que se muestran como viñetas distribuidos en columnas.
 * @param int $num_columnas Número de columnas para distribuir los ítems. Por defecto 2.
 * @return void
 * @author Jair Carvajal
 */
private function renderizarTarjetaLista(string $titulo, string $texto, array $lista_textos, int $num_columnas = 2): void {
    $color             = $this->colores_reporte[0];
    $total             = count($lista_textos);
    $por_columna       = (int) ceil($total / $num_columnas);
    $ancho_columna     = (int) round(100 / $num_columnas);
    $rutas_icono_menos = '<path fill-rule="evenodd" d="M10.5 8a.5.5 0 0 1-.5.5H6a.5.5 0 0 1 0-1h4a.5.5 0 0 1 .5.5z"/><path d="M3 0h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2v-1h1v1a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v1H1V2a2 2 0 0 1 2-2z"/><path d="M1 5v-.5a.5.5 0 0 1 1 0V5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0V8h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1zm0 3v-.5a.5.5 0 0 1 1 0v.5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1H1z"/>';
    $insignia          = base64_encode($this->generarBadgeContadorSVG($rutas_icono_menos, $total));

    $html_columnas = '';

    for ($i = 0; $i < $num_columnas; $i++) {
        $items      = array_slice($lista_textos, $i * $por_columna, $por_columna);
        $html_items = implode('', array_map(
            fn($texto_item) => '<div style="font-size: 10px; color: #4D4D4F; line-height: 5.5mm;">&#8226; ' . htmlspecialchars($texto_item) . '</div>',
            $items
        ));
        $html_columnas .= '<td style="width: ' . $ancho_columna . '%; vertical-align: top;">' . $html_items . '</td>';
    }

    $this->mpdf->WriteHTML('
        <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; margin-bottom: 4mm; background-color: #FFFFFF; overflow: hidden;">
            <div style="padding: 4mm;">
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>
                        <td style="font-size: 13px; font-weight: bold; color: #1C1C1D; vertical-align: middle;">
                            ' . htmlspecialchars($titulo) . '
                        </td>
                        <td style="text-align: right; vertical-align: middle; width: 10%; white-space: nowrap;">
                            <img src="data:image/svg+xml;base64,' . $insignia . '" style="height: 5mm; vertical-align: middle;">
                        </td>
                    </tr>
                </table>

                <div style="font-size: 10px; color: #4D4D4F; margin-bottom: 3mm;">
                    ' . htmlspecialchars($texto) . '
                </div>
                <table style="width: 100%; border-collapse: collapse;">
                    <tr>' . $html_columnas . '</tr>
                </table>
            </div>
        </div>
    ');

