/**
 * Renderiza la página de listas en línea del reporte.
 * Muestra las categorías presentes en listas_linea como secciones con sus datos.
 * Si el array está vacío o no existe, muestra la card predeterminada de sin resultados.
 * Si una categoría no tiene datos válidos, la omite y la acumula para el bloque de sin resultados.
 *
 * @param float $altura_inicial Posición Y en milímetros desde donde empieza el contenido. Por defecto 48.
 * @return void
 * @author Jair Carvajal
 */
public function paginaListasLinea(float $altura_inicial = 48): void {
    $color        = $this->colores_reporte[0];
    $datos        = $this->datos_antecedente ?? [];
    $listas_linea = $datos['listas_linea'] ?? [];

    $this->tituloSeccionHoja((object) [
        'y'      => 35,
        'width'  => 70,
        'titulo' => 'LISTAS EN LINEA',
        'color'  => $color,
    ]);

    $this->mpdf->SetY($altura_inicial);

    if (empty($listas_linea)) {
        $this->mpdf->WriteHTML('
            <div style="border: 0.3mm solid #E0E0E0; border-radius: 2mm; background-color: #FFFFFF; overflow: hidden;">
                <div style="padding: 4mm; text-align: center; color: #9E9E9E; font-size: 10px; font-style: italic;">
                    Sin datos encontrados
                </div>
            </div>
        ');
        return;
    }

    $sin_resultado_titulos = [];

    foreach ($listas_linea as $etiqueta => $datos_categoria) {
        if ($this->esSinDatosPrecargados($datos_categoria)) {
            $sin_resultado_titulos[] = (string) $etiqueta;
            continue;
        }

        $this->renderizarSeccionConDatos((string) $etiqueta, (array) $datos_categoria, $sin_resultado_titulos, 'LISTAS EN LINEA');
    }

    if (!empty($sin_resultado_titulos)) {
        $this->renderizarTarjetaLista(
            'Fuentes sin resultados encontrados',
            'Se realizó una búsqueda en las siguientes fuentes y no se encontraron registros relacionados con la persona consultada.',
            $sin_resultado_titulos,
            2
        );
    }
}

