foreach ($categorias as $clave => $etiqueta) {
    $datos_categoria = $listas_linea[$clave] ?? null;

    if ($this->esSinDatosPrecargados($datos_categoria)) {
        $sin_datos_titulos[] = $etiqueta;
    } else {
        $this->renderizarSeccionConDatos($etiqueta, (array) $datos_categoria, $sin_resultado_titulos, 'LISTAS EN LINEA');
    }
}

$tiene_sin_hallazgos = !empty($sin_datos_titulos) || !empty($sin_resultado_titulos);
